// Provisional SVG illustration of each layer (viewBox 420x145).
const svg=(body)=>`<svg viewBox="0 0 420 145" aria-hidden="true"><defs><linearGradient id="bun" x2="0" y2="1"><stop stop-color="#ffca63"/><stop offset=".6" stop-color="#cc661c"/><stop offset="1" stop-color="#8d340e"/></linearGradient><linearGradient id="meat" x2="0" y2="1"><stop stop-color="#793419"/><stop offset=".5" stop-color="#482011"/><stop offset="1" stop-color="#26140e"/></linearGradient><linearGradient id="cheese" x2="0" y2="1"><stop stop-color="#ffd64b"/><stop offset="1" stop-color="#f18c05"/></linearGradient></defs>${body}</svg>`;
// Sauce drizzle shared by ketchup and maionese; only the colours differ.
const sauce=(fill,stroke,shine)=>svg(`<path d="M28 67Q70 38 112 56Q152 33 198 53Q245 34 290 53Q346 38 392 67Q377 89 354 78Q343 106 328 80Q299 92 269 79Q238 105 218 80Q177 90 153 80Q123 106 108 79Q58 94 28 67Z" fill="${fill}" stroke="${stroke}" stroke-width="2"/><path d="M50 63Q115 51 166 63T285 63T370 64" fill="none" stroke="${shine}" stroke-width="5" stroke-linecap="round"/>`);
// Cebola crispy: a low mound of golden crumbs (deterministic, like the sesame seeds).
function crispyOnion(){let c='<path d="M40 82Q60 62 100 64Q150 50 210 54Q270 50 320 64Q360 62 380 82Q350 96 300 90Q250 99 210 93Q160 99 120 90Q70 96 40 82Z" fill="#b8732a"/>';for(let i=0;i<70;i++){const x=40+(i*97%340),d=Math.abs(x-210)/170,y=72-(1-d*d)*14+(i*37%16),r=5+(i*13%6);c+=`<ellipse cx="${x}" cy="${y}" rx="${r+3}" ry="${r*.6}" fill="${['#c98a2e','#dca146','#a8651c','#e8b860'][i%4]}" transform="rotate(${i*53%60-30} ${x} ${y})"/>`;}return svg(c);}
// Cheddar (Cheddar Duplo): creamy orange sauce with rounded drips over the edge.
function cheddar(){const drips=[[52,22],[110,34],[176,18],[238,40],[300,26],[362,30]].map(([x,l])=>`<path d="M${x-11} 78V${78+l}a11 11 0 0 0 22 0V78Z" fill="#f08a06"/>`).join('');return svg(`${drips}<path d="M14 66Q210 34 406 66Q412 80 396 84Q210 102 24 84Q8 80 14 66Z" fill="#f59a0c"/><path d="M34 64Q210 42 386 64" stroke="#ffc24a" fill="none" stroke-width="4"/>`);}
export function art(id){if(id==='crispyOnion')return crispyOnion();if(id==='cheddar')return cheddar();if(id==='ketchup')return sauce('#c8240f','#8f1708','#f0705a');if(id==='mayo')return sauce('#fbf1d6','#dcc89a','#ffffff');if(id==='top'){let seeds='';for(let i=0;i<42;i++){const x=45+(i*73%325),y=47+(i*31%40);seeds+=`<ellipse cx="${x}" cy="${y}" rx="4" ry="1.7" fill="#ffeab1" transform="rotate(${i*47%100-50} ${x} ${y})"/>`;}return svg(`<path d="M20 109C24 4 383 4 400 109Q210 154 20 109" fill="url(#bun)"/><path d="M32 106Q210 145 388 106" fill="none" stroke="#eaa251" stroke-width="5"/>${seeds}`)}if(id==='bottom')return svg('<path d="M23 63Q210 32 397 63L390 107Q210 158 30 106Z" fill="url(#bun)"/><ellipse cx="210" cy="65" rx="187" ry="28" fill="#edaf56"/><path d="M35 101Q210 139 382 104" fill="none" stroke="#a74c15" stroke-width="5"/>');if(id==='meat')return svg('<path d="M15 63Q25 48 45 49Q80 35 109 48Q140 33 170 46Q200 34 230 44Q270 35 300 45Q350 37 397 61L405 88Q390 125 345 118Q300 133 270 120Q210 134 166 121Q120 133 87 118Q39 126 17 98Z" fill="url(#meat)"/><path d="M37 63L82 95M95 56L145 107M165 54L215 107M240 54L285 106M315 57L362 96" stroke="#21110b" stroke-width="8" stroke-linecap="round"/><path d="M28 66Q210 28 395 66" fill="none" stroke="#ae6336" stroke-width="5"/>');if(id==='cheese')return svg('<path d="M16 64L166 40L399 62L350 89L305 120L251 81L198 104L135 76L79 108L28 81Z" fill="url(#cheese)"/><path d="M32 64L168 47L380 64" stroke="#ffe774" fill="none" stroke-width="4"/>');if(id==='lettuce'){let l='';for(let i=0;i<14;i++){const x=22+i*28,y=64+(i%3)*8;l+=`<path d="M${x} ${y}q-15-22 5-30q13-14 24 4q24-8 27 10q13 20-13 29q-10 19-26 0q-20 8-17-13" fill="${['#639a1c','#8eb72b','#447b16'][i%3]}" stroke="#a4c747" stroke-width="2"/>`;}return svg(l)}if(id==='tomato')return svg([75,192,313].map(x=>`<ellipse cx="${x}" cy="75" rx="67" ry="24" fill="#c12a0f"/><ellipse cx="${x}" cy="67" rx="66" ry="23" fill="#f34820" stroke="#ff8060" stroke-width="3"/><ellipse cx="${x}" cy="66" rx="45" ry="13" fill="#d33215"/><path d="M${x-35} 66h70M${x} 56v22" stroke="#ffad61" stroke-width="3"/>`).join(''));if(id==='onion')return svg([80,198,318].map(x=>`<ellipse cx="${x}" cy="73" rx="70" ry="23" fill="#ead7a8"/><ellipse cx="${x}" cy="67" rx="65" ry="20" fill="#fff4d3"/><ellipse cx="${x}" cy="67" rx="51" ry="13" fill="#fff4d3" stroke="#cdb79a" stroke-width="3"/>`).join(''));return svg([65,150,245,330].map((x,i)=>`<ellipse cx="${x}" cy="70" rx="44" ry="18" fill="#517219"/><ellipse cx="${x}" cy="65" rx="43" ry="16" fill="#93a636" stroke="#466919" stroke-width="4"/><ellipse cx="${x}" cy="65" rx="24" ry="8" fill="#bdc866"/>`).join(''))}
